  ('home', 'home', '{"featured":[{"id":"kekova-klasik","kind":"event"},{"id":"deneme-dalisi","kind":"event"},{"id":"kiyi-tirmanisi","kind":"event"},{"id":"likya-kayak-konfor","kind":"event"},{"id":"raja-ampat-2027","kind":"post"}],"hero":{"heading":{"de":"Tauchen, Seekajak und Outdoor in Kaş und Kekova","en":"Diving, sea kayaking and outdoors in Kaş and Kekova","fr":"Plongée, kayak de mer et plein air à Kaş et Kekova","tr":"Kaş ve Kekova''da dalış, deniz kanosu ve doğa"},"subheading":{"de":"Seit 2002 in Kaş: unter und auf dem Meer an der lykischen Küste, in kleinen Gruppen.","en":"In Kaş since 2002: under and on the sea along the Lycian coast, in small groups.","fr":"À Kaş depuis 2002 : sous la mer et sur l''eau le long de la côte lycienne, en petits groupes.","tr":"2002''den beri Kaş''ta: Likya kıyısında denizin altında ve üstünde, küçük gruplarla."},"tiles":[{"category":"diving","media":"hero-diving","tagline":{"de":"Mehr als 30 Tauchplätze","en":"More than 30 dive sites","fr":"Plus de 30 sites de plongée","tr":"30''u aşkın dalış noktası"}},{"category":"seaKayak","media":"hero-sea-kayak","tagline":{"de":"Paddeln über der versunkenen Stadt","en":"Paddle over the sunken city","fr":"Pagayer au-dessus de la cité engloutie","tr":"Batık şehir üzerinde kürek"}},{"category":"outdoor","media":"hero-outdoor","tagline":{"de":"Wandern, Radfahren, Coasteering","en":"Hiking, cycling, coasteering","fr":"Randonnée, vélo, coasteering","tr":"Yürüyüş, bisiklet, coasteering"}}]},"origin":"mockup","quickLinks":[{"media":"kas-town-view-1","page":"transport","text":{"de":"Flughafentransfers und Unterkunft","en":"Airport transfers and accommodation","fr":"Transferts aéroport et hébergement","tr":"Havalimanı transferleri ve konaklama"}},{"media":"book-tropical-spread-1","page":"shop","text":{"de":"Unsere Bücher über das Unterwasser-Kaş","en":"Our books on underwater Kaş","fr":"Nos livres sur le Kaş sous-marin","tr":"Kaş sualtı kitaplarımız"}}],"seo":{"description":{"de":"Seit 2002 in Kaş: Tauchen, Seekajak, Wandern und Radfahren in Kaş und Kekova, unter und auf dem Meer an der lykischen Küste, in kleinen Gruppen.","en":"In Kaş since 2002: diving, sea kayaking, hiking and cycling in Kaş and Kekova, under and on the sea along the Lycian coast, always in small groups.","fr":"À Kaş depuis 2002 : plongée, kayak de mer, randonnée et vélo à Kaş et Kekova, sous la mer et sur l''eau le long de la côte lycienne, en petits groupes.","tr":"2002''den beri Kaş''ta: Kaş ve Kekova''da dalış, deniz kanosu, yürüyüş ve bisiklet; Likya kıyısında denizin altında ve üstünde, küçük gruplarla etkinlikler."},"title":{"de":"Tauchen, Seekajak und Outdoor in Kaş und Kekova","en":"Diving, Sea Kayaking and Outdoors in Kaş & Kekova","fr":"Plongée, kayak de mer, plein air à Kaş et Kekova","tr":"Kaş''ta Dalış, Deniz Kanosu ve Doğa Etkinlikleri"}},"sourceRefs":["https://dragomanseakayak.com/tr/","https://dragoman-turkey.com/tr/dragoman/","https://dragoman-turkey.com/tr/diving/"],"translationOrigin":{"de":"mockup","en":"mockup","fr":"mockup"},"why":[{"text":{"de":"Ein Team, das Meer, Küste, Wetter und Routen von Kaş und Kekova genau kennt.","en":"A team that knows the sea, coastline, weather and routes of Kaş and Kekova closely.","fr":"Une équipe qui connaît de près la mer, la côte, la météo et les itinéraires de Kaş et Kekova.","tr":"Kaş ve Kekova''nın denizini, kıyılarını, hava koşullarını ve rotalarını yakından tanıyan bir ekip."},"title":{"de":"Mehr als 25 Jahre Erfahrung vor Ort","en":"More than 25 years of local experience","fr":"Plus de 25 ans d''expérience locale","tr":"25 yılı aşan yerel deneyim"}},{"text":{"de":"Route, Wetter und Seegang werden vor jeder Aktivität geprüft; Ausrüstung und Abläufe folgen festen Standards.","en":"Route, weather and sea conditions are assessed before every activity; equipment and procedures follow set standards.","fr":"L''itinéraire, la météo et l''état de la mer sont évalués avant chaque activité ; équipement et pratiques suivent des standards établis.","tr":"Rota, hava ve deniz koşulları her etkinlik öncesinde değerlendirilir; ekipman ve uygulamalar standartlara uygun hazırlanır."},"title":{"de":"Sicherheit zuerst","en":"Safety first","fr":"La sécurité d''abord","tr":"Önce güvenlik"}},{"text":{"de":"Unsere Tauchlehrer und Guides sind seit vielen Jahren in diesen Gewässern und auf diesen Pfaden unterwegs.","en":"Our instructors and guides have worked in these waters and on these trails for many years.","fr":"Nos moniteurs et guides travaillent depuis de nombreuses années sur ces eaux et ces sentiers.","tr":"Eğitmenlerimiz ve rehberlerimiz uzun yıllardır bu sularda ve patikalarda çalışıyor."},"title":{"de":"Ein langjähriges Expertenteam","en":"A long-standing expert team","fr":"Une équipe d''experts fidèle","tr":"Uzun soluklu uzman ekip"}},{"text":{"de":"Mit kleinen Gruppen und naturverträglichen Touren erkunden wir das Meeresschutzgebiet Kaş-Kekova und schützen es zugleich.","en":"Small groups and nature-friendly trips let us explore the Kaş-Kekova Marine Protected Area while protecting it.","fr":"Petits groupes et voyages respectueux de la nature : nous explorons l''Aire Marine Protégée de Kaş-Kekova tout en la préservant.","tr":"Küçük gruplar ve doğaya saygılı yolculuklarla Kaş-Kekova Özel Deniz Koruma Alanı''nı koruyarak keşfediyoruz."},"title":{"de":"Respekt vor der Natur","en":"Respect for nature","fr":"Le respect de la nature","tr":"Doğaya saygı"}}]}'::jsonb, '{"/hero/heading":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"11d84adfc9f12c","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"11d84adfc9f12c","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"11d84adfc9f12c","origin":"seed"}},"/hero/subheading":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"146f1d2a4d131b","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"146f1d2a4d131b","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"146f1d2a4d131b","origin":"seed"}},"/hero/tiles/0/tagline":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1a0f05ab69d953","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1a0f05ab69d953","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1a0f05ab69d953","origin":"seed"}},"/hero/tiles/1/tagline":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0e82ec42e92828","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0e82ec42e92828","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0e82ec42e92828","origin":"seed"}},"/hero/tiles/2/tagline":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0c2578ced08cf9","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0c2578ced08cf9","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0c2578ced08cf9","origin":"seed"}},"/quickLinks/0/text":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"10558bdd8c866f","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"10558bdd8c866f","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"10558bdd8c866f","origin":"seed"}},"/quickLinks/1/text":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1d8b498217f0d6","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1d8b498217f0d6","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1d8b498217f0d6","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"17c28aa43f46fd","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"17c28aa43f46fd","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"17c28aa43f46fd","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1369aeef973d45","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1369aeef973d45","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1369aeef973d45","origin":"seed"}},"/why/0/text":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"04dbe91286331e","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"04dbe91286331e","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","has