  ('post', 'kekova-bati-turu', '{"body":{"de":[{"text":"Diese ganztägige Reise ist für fortgeschrittene Paddler gedacht und verbindet Abenteuer, Geschichte und Naturschönheit. Paddeln Sie durch kristallklares Wasser, schnorcheln Sie über den antiken Ruinen von Aperlai und wandern Sie auf dem Lykischen Weg.","type":"p"},{"text":"Warum diese Tour?","type":"h2"},{"items":["Zwei versunkene Städte: Kekova und Aperlai","Kleine Gruppe mit professionellen Guides","Schnorcheln in der Bucht Tersane und über den versunkenen Ruinen von Aperlai","Wanderung auf einem kurzen Abschnitt des Lykischen Wegs","Kajaksegeln, wenn die Bedingungen passen","Lokales Mittagessen in einem Fischerhaus"],"type":"ul"},{"text":"Paddelstrecke: 15 km. Wanderung: 1,5 km.","type":"p"}],"en":[{"text":"This full-day journey is designed for intermediate to advanced paddlers, offering a blend of adventure, history and natural beauty. Paddle through crystal-clear water, snorkel above ancient ruins in Aperlai and hike along the Lycian Way.","type":"p"},{"text":"Why this tour?","type":"h2"},{"items":["Two sunken cities: Kekova and Aperlai","Small group with professional guides","Snorkelling in Tersane Bay and over the sunken ruins of Aperlai","A hike on a short section of the Lycian Way","Kayak sailing when conditions allow","Local lunch at a fisherman''s house"],"type":"ul"},{"text":"Paddle distance: 15 km. Hiking: 1.5 km.","type":"p"}],"fr":[{"text":"Ce voyage d''une journée est conçu pour les pagayeurs de niveau intermédiaire à avancé et mêle aventure, histoire et beauté naturelle. Pagayez dans des eaux cristallines, faites du snorkeling au-dessus des ruines d''Aperlai et randonnez sur le chemin lycien.","type":"p"},{"text":"Pourquoi cette excursion ?","type":"h2"},{"items":["Deux cités englouties : Kekova et Aperlai","Petit groupe avec des guides professionnels","Snorkeling dans la baie de Tersane et sur les ruines englouties d''Aperlai","Randonnée sur une courte section du chemin lycien","Voile en kayak si les conditions le permettent","Déjeuner local chez un pêcheur"],"type":"ul"},{"text":"Distance de pagaie : 15 km. Randonnée : 1,5 km.","type":"p"}],"tr":[{"text":"Bu tam günlük yolculuk orta ve ileri seviye kanocular için tasarlanmıştır ve macera, tarih ve doğal güzelliği bir araya getirir. Berrak sularda kürek çekerken Aperlai''deki antik kalıntıların üzerinde şnorkelle yüzebilir ve Likya Yolu boyunca yürüyebilirsiniz.","type":"p"},{"text":"Neden bu tur?","type":"h2"},{"items":["İki batık şehir: Kekova ve Aperlai","Profesyonel rehberlerle küçük grup","Tersane Koyu''nda ve Aperlai''nin batık kalıntılarında şnorkel","Likya Yolu''nun kısa bir bölümünde yürüyüş","Hava uygunsa kayak yelkeni","Balıkçı evinde yerel öğle yemeği"],"type":"ul"},{"text":"Kürek mesafesi: 15 km. Yürüyüş: 1,5 km.","type":"p"}]},"cover":"kayak-aperlai-3","date":"2025-05-30","excerpt":{"de":"Eine Route für fortgeschrittene Paddler zu den versunkenen Städten Kekova und Aperlai an einem Tag.","en":"A route for intermediate to advanced paddlers that explores the sunken cities of Kekova and Aperlai in one day.","fr":"Un itinéraire pour pagayeurs intermédiaires à avancés, à la découverte des cités englouties de Kekova et d''Aperlai en une journée.","tr":"Kekova ve Aperlai''nin batık şehirlerini tek günde keşfedeceğiniz, orta ve ileri seviye için bir rota."},"id":"kekova-bati-turu","origin":"cloner","relatedEvents":["kekova-bati"],"seo":{"description":{"de":"Ein ganzer Tag für Fortgeschrittene: die versunkenen Städte Kekova und Aperlai, Schnorcheln, Wandern auf dem Lykischen Weg und Mittagessen beim Fischer.","en":"A full day for intermediate to advanced paddlers: the sunken cities of Kekova and Aperlai, snorkelling, a Lycian Way hike and lunch at a fisherman''s house.","fr":"Une journée pour pagayeurs intermédiaires et confirmés : cités englouties de Kekova et d''Aperlai, snorkeling, voie lycienne et déjeuner chez un pêcheur.","tr":"Orta ve ileri seviye için tam gün: Kekova ve Aperlai batık şehirleri, şnorkel, Likya Yolu''nda kısa yürüyüş ve balıkçı evinde öğle yemeği. 15 km kürek."},"title":{"de":"Kekova West: zwei versunkene Städte an einem Tag","en":"Kekova West Tour: Two Sunken Cities in One Day","fr":"Kekova Ouest : deux cités englouties en un jour","tr":"Kekova Batı Turu: İki Batık Şehir, Tek Gün"}},"slug":{"de":"seekajak-kekova-west-tour","en":"sea-kayak-kekova-west-tour","fr":"kayak-de-mer-kekova-ouest","tr":"deniz-kanosu-kekova-bati-turu"},"sourceRefs":["https://dragoman-turkey.com/tr/dragoman-blog-tr/sea-kayak-kekova-west-tour/","1683","508","1682"],"status":"published","title":{"de":"Seekajak-Tour Kekova West","en":"Sea Kayak Kekova West Tour","fr":"Kayak de mer Kekova Tour Ouest","tr":"Deniz Kanosu Kekova Batı Turu"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1235311d4540a2","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1235311d4540a2","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1235311d4540a2","origin":"seed"}},"/excerpt":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1bf3b8334acce4","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1bf3b8334acce4","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1bf3b8334acce4","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1654c350aec295","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1654c350aec295","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1654c350aec295","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"06dd40ef928ad7","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"06dd40ef928ad7","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"06dd40ef928ad7","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"08159e13f5636a","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"08159e13f5636a","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"08159e13f5636a","origin":"seed"}}}'::jsonb, 'published'),
  ('post', 'kekova-dogu-turu', '{"body":{"de":[{"text":"Eine Seekajakreise durch die Region Kekova, wo antike Geschichte und unberührte Natur zusammentreffen. Paddeln Sie über versunkene Ruinen, schwimmen Sie in einsamen Buchten, beobachten Sie Tiere und paddeln Sie an einer Höhle vorbei. Die Tour richtet sich an fortgeschrittene Paddler oder Kajakbegeisterte mit guter Kondition.","type":"p"},{"items":["Die versunkene Stadt ist geschützt, Schwimmen ist dort verboten, aber vom Kajak aus sehen Sie die Ruinen aus nächster Nähe.","Wildziegen, die oft an Felsen und auf Inseln zu sehen sind.","Eine Meereshöhle, einst Heimat der Mittelmeer-Mönchsrobben.","Der Bach von Andriake, ein geschütztes Nistgebiet der Meeresschildkröten."],"type":"ul"},{"text":"Paddelstrecke: 17 km.","type":"p"}],"en":[{"text":"A sea kayaking journey through the Kekova region, where ancient history and unspoilt nature meet. Paddle over sunken ruins, swim in secluded bays, spot wildlife and paddle by a cave. The tour is aimed at intermediate to advanced paddlers or kayak enthusiasts in good physical condition for longer paddling.","type":"p"},{"items":["The Sunken City is protected, so swimming is not allowed, but you get the closest view of the ruins from your kayak.","Wild goats, often spotted on the cliffs and islands.","A sea cave, once home to Mediterranean monk seals.","The Andriake stream, a protected nesting area for sea turtles."],"type":"ul"},{"text":"Paddle distance: 17 km.","type":"p"}],"fr":[{"text":"Un voyage en kayak de mer dans la région de Kekova, où l''histoire ancienne et la nature préservée se rejoignent. Pagayez au-dessus des ruines englouties, nagez dans des baies isolées, observez la faune et pagayez près d''une grotte. Ce tour s''adresse aux pagayeurs intermédiaires à avancés ou aux passionnés en bonne condition physique.","type":"p"},{"items":["La zone étant protégée, la baignade est interdite au-dessus de la cité engloutie, mais vous voyez les ruines au plus près depuis votre kayak.","Les chèvres sauvages, souvent aperçues sur les falaises et les îles.","Une grotte marine autrefois habitée par les phoques moines de Méditerranée.","Le ruisseau d''Andriake, zone protégée de nidification des tortues marines."],"type":"ul"},{"text":"Distance parcourue en kayak : 17 km.","type":"p"}],"tr":[{"text":"Antik tarih ile bozulmamış doğanın birleştiği Kekova bölgesinde bir deniz kayağı yolculuğu. Batık kalıntıların üzerinden kürek çekin, tenha koylarda yüzün, yaban hayatını gözlemleyin ve bir mağaranın yanından geçin. Tur, orta ve ileri seviye kanocular ya da uzun süre kürek çekebilecek kondisyondaki katılımcılar içindir.","type":"p"},{"items":["Korunan alan olduğu için Batık Şehir''de yüzülmez; kalıntıları kanodan en yakından görürsünüz.","Kayalıklarda ve adalarda sıkça görülen yaban keçileri.","Bir zamanlar Akdeniz foklarının yaşadığı deniz mağarası.","Kaplumbağaların korunan üreme alanı Andriake Deresi."],"type":"ul"},{"text":"Kürek mesafesi: 17 km.","type":"p"}]},"cover":"kayak-kekova-east-2","date":"2025-05-30","excerpt":{"de":"Versunkene Ruinen, einsame Buchten, eine Meereshöhle und Schildkröten am Bach von Andriake.","en":"Sunken ruins, secluded bays, a sea cave and turtles on the Andriake stream.","fr":"Ruines englouties, baies isolées, une grotte marine et des tortues sur le ruisseau d''Andriake.","tr":"Batık kalıntılar, tenha koylar, bir deniz mağarası ve Andriake deresinde kaplumbağalar."},"id":"kekova-dogu-turu","origin":"cloner","relatedEvents":["kekova-dogu"],"seo":{"description":{"de":"Versunkene Ruinen, einsame Buchten, eine Meereshöhle, in der einst Mönchsrobben lebten, und Schildkröten bei Andriake: 17 km Seekajak für geübte, fitte Paddler.","en":"Sunken ruins, secluded bays, a sea cave once home to monk seals and sea turtles on the Andriake stream: a 17 km sea kayaking day for fit, experienced paddlers.","fr":"Ruines englouties, criques isolées, une grotte marine jadis habitée par des phoques moines et des tortues à Andriake : 17 km de kayak pour pagayeurs en forme.","tr":"Kekova''da batık kalıntılar, tenha koylar, bir zamanlar fokların yaşadığı deniz mağarası ve Andriake deresinde deniz kaplumbağaları: 17 km''lik deniz kayağı günü."},"title":{"de":"Kekova Ost: Meereshöhle, Buchten und Schildkröten","en":"Kekova East Tour: Sea Cave, Bays and Sea Turtles","fr":"Kekova Est : grotte marine, criques et tortues","tr":"Kekova Doğu Turu: Mağara, Koylar ve Kaplumbağalar"}},"slug":{"de":"seekajak-kekova-ost-tour","en":"sea-kayak-kekova-east-tour","fr":"kayak-de-mer-kekova-est","tr":"deniz-kayagi-kekova-dogu-turu"},"sourceRefs":["https://dragoman-turkey.com/tr/dragoman-blog-tr/sea-kayak-kekova-east-tour/","1677","544","1676"],"status":"published","title":{"de":"Seekajak-Tour Kekova Ost","en":"Sea Kayak Kekova East Tour","fr":"Tour en kayak de mer Kekova Est","tr":"Deniz Kayağı Kekova Doğu Turu"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1fc1ae1588a4a2","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1fc1ae1588a4a2","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1fc1ae1588a4a2","origin":"seed"}},"/excerpt":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"029d189827f575","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"029d189827f575","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"029d189827f575","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"124c310dc258f6","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"124c310dc258f6","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"124c310dc258f6","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1aa18924ce8bf2","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1aa18924ce8bf2","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1aa18924ce8bf2","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"178416a94a1067","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"178416a94a1067","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"178416a94a1067","origin":"seed"}}}'::jsonb, 'published'),
  ('post', 'kekova-klasik-turu', '{"body":{"de":[{"text":"Entdecken Sie die atemberaubende Schönheit von Kekova auf diesem Seekajak-Abenteuer! Paddeln Sie durch kristallklares Wasser, erkunden Sie antike lykische Ruinen, gleiten Sie über die versunkene Stadt und genießen Sie ein Essen mit herrlicher Aussicht. Ein Erlebnis in kleiner Gruppe für Abenteuerlustige, Geschichtsfans und Naturliebhaber.","type":"p"},{"text":"Zur Bucht Tersane paddeln","type":"h2"},{"text":"Vorbei an kleinen Inseln mit römischen und lykischen Ruinen erreichen Sie die Bucht Tersane mit den Resten einer antiken lykischen Werft. Bei einer kurzen Pause gibt es Snacks von Ihrem Guide.","type":"p"},{"text":"Die versunkene Stadt und Simena","type":"h2"},{"items":["Im Gänsemarsch am Rand der berühmten versunkenen Stadt entlang; vorher erzählt Ihr Guide kurz ihre Geschichte.","Da Schwimmen im Schutzgebiet verboten ist, erkunden Sie die Ruinen vom Kajak aus.","In Simena (Kaleköy), einem Dorf ohne Straßenanbindung, bietet die Burg einen Panoramablick über Kekova und die Inseln.","Freie Zeit in Simena: Steingassen, hausgemachtes Eis oder ein erfrischendes Bad."],"type":"ul"},{"text":"Paddelstrecke: 8 km.","type":"p"}],"en":[{"text":"Discover the breathtaking beauty of Kekova on this sea kayaking adventure! Paddle through crystal-clear water, explore ancient Lycian ruins, glide over the Sunken City and enjoy a delicious meal with spectacular views. This small-group experience is perfect for adventure seekers, history lovers and nature enthusiasts.","type":"p"},{"text":"Paddle to Tersane Bay","type":"h2"},{"text":"Glide past small islands with Roman and Lycian ruins to reach Tersane Bay, home to the ruins of an ancient Lycian shipyard. Take a short break and refuel with snacks provided by your guide.","type":"p"},{"text":"The Sunken City and Simena","type":"h2"},{"items":["Paddle single file along the edge of the famous Sunken City; before reaching the ruins your guide shares a brief history of the settlement.","Since swimming is not allowed in this protected area, you explore from your kayak.","In Simena (Kaleköy), a village with no road access, the castle offers panoramic views of Kekova and the islands.","Free time in Simena: stone streets, homemade ice cream or a refreshing swim."],"type":"ul"},{"text":"Paddle distance: 8 km.","type":"p"}],"fr":[{"text":"Découvrez la beauté à couper le souffle de Kekova lors de cette aventure en kayak de mer ! Pagayez dans des eaux cristallines, explorez des ruines lyciennes, glissez au-dessus de la cité engloutie et dégustez un délicieux repas avec vue. Cette expérience en petit groupe est parfaite pour les amateurs d''aventure, d''histoire et de nature.","type":"p"},{"text":"Pagayer jusqu''à la baie de Tersane","type":"h2"},{"text":"Glissez le long de petites îles aux ruines romaines et lyciennes jusqu''à la baie de Tersane, qui abrite les ruines d''un ancien chantier naval lycien. Courte pause et en-cas fournis par votre guide.","type":"p"},{"text":"La cité engloutie et Simena","type":"h2"},{"items":["Pagayez en file indienne le long de la célèbre cité engloutie ; avant les ruines, votre guide vous en raconte brièvement l''histoire.","La baignade étant interdite dans cette zone protégée, vous explorez depuis votre kayak.","À Simena (Kaleköy), village sans accès routier, le château offre une vue panoramique sur Kekova et les îles.","Temps libre à Simena : ruelles pavées, glace maison ou baignade rafraîchissante."],"type":"ul"},{"text":"Distance de pagayage : 8 km.","type":"p"}],"tr":[{"text":"Kekova''nın nefes kesici güzelliklerini bu deniz kayağı macerasında keşfedin! Berrak suların üzerinde kürek çekin, antik Likya kalıntılarını keşfedin, Batık Şehir''in üzerinden süzülün ve manzara eşliğinde lezzetli bir yemek yiyin. Bu küçük grup deneyimi macera arayanlar, tarih severler ve doğa tutkunları için.","type":"p"},{"text":"Tersane Koyu''na kürek","type":"h2"},{"text":"Küçük adaların etrafında Roma ve Likya kalıntılarının yanından geçerek antik bir Likya gemi yapım atölyesinin kalıntılarının bulunduğu Tersane Koyu''na ulaşırsınız. Kısa bir molada rehberinizin getirdiği atıştırmalıklarla enerjinizi tazelersiniz.","type":"p"},{"text":"Batık Şehir ve Simena","type":"h2"},{"items":["Ünlü Batık Şehir''in kenarından tek sıra halinde kürek çekin; kalıntılara yaklaşmadan önce rehberiniz yerleşimin kısa tarihçesini anlatır.","Korunan alanda yüzmek yasak olduğundan kalıntıları kanonuzdan izlersiniz.","Karayolu olmayan Simena''da (Kaleköy) kalenin tepesinden Kekova ve adaların panoramik manzarası.","Simena''da serbest zaman: taş sokaklar, ev yapımı dondurma ya da serin bir yüzme."],"type":"ul"},{"text":"Kürek mesafesi: 8 km.","type":"p"}]},"cover":"kayak-kekova-classic-2","date":"2025-05-30","excerpt":{"de":"Durch kristallklares Wasser paddeln, lykische Ruinen erkunden und über die versunkene Stadt gleiten: ein Tag in kleiner Gruppe.","en":"Paddle through crystal-clear water, explore Lycian ruins and glide over the Sunken City: a day in a small group.","fr":"Pagayez dans une eau cristalline, explorez les ruines lyciennes et glissez au-dessus de la cité engloutie : une journée en petit groupe.","tr":"Berrak suların üzerinde kürek çekin, Likya kalıntılarını keşfedin ve Batık Şehir''in üzerinden süzülün: küçük grupla bir gün."},"id":"kekova-klasik-turu","origin":"cloner","relatedEvents":["kekova-klasik"],"seo":{"description":{"de":"Ein Seekajak-Tag in kleiner Gruppe bei Kekova: Inseln mit römischen und lykischen Ruinen, Pause in Tersane, die versunkene Stadt und ein Essen mit Aussicht.","en":"A small-group day of sea kayaking in Kekova: islands with Roman and Lycian ruins, a break in Tersane Bay, paddling past the Sunken City and lunch with a view.","fr":"Une journée de kayak de mer en petit groupe à Kekova : îlots aux ruines romaines et lyciennes, pause dans la baie de Tersane, cité engloutie et repas avec vue.","tr":"Küçük grupla bir günlük Kekova deniz kayağı turu: Roma ve Likya kalıntılı adalar, Tersane Koyu''nda mola, Batık Şehir kıyısında kürek ve manzaralı öğle yemeği."},"title":{"de":"Kekova Klassik: im Kajak von Tersane nach Simena","en":"Kekova Classic Tour: From Tersane Bay to Simena","fr":"Tour classique de Kekova : de Tersane à Simena","tr":"Kekova Klasik Turu: Tersane Koyu''ndan Simena''ya"}},"slug":{"de":"seekajak-kekova-klassik-tour","en":"sea-kayak-kekova-classic-tour","fr":"kayak-de-mer-kekova-classique","tr":"deniz-kayagi-kekova-klasik-turu"},"sourceRefs":["https://dragoman-turkey.com/tr/dragoman-blog-tr/sea-kayak-kekova-classic-tour/","1671","567","1670"],"status":"published","title":{"de":"Seekajak-Tour Kekova Klassik","en":"Sea Kayak Kekova Classic Tour","fr":"Tour classique en kayak de mer à Kekova","tr":"Deniz Kayağı Kekova Klasik Turu"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"08406eb411e2bf","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"08406eb411e2bf","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"08406eb411e2bf","origin":"seed"}},"/excerpt":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"164e802fed8005","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"164e802fed8005","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"164e802fed8005","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"057b33853ff6a9","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"057b33853ff6a9","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"057b33853ff6a9","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"059b230962fcb1","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"059b230962fcb1","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"059b230962fcb1","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0a9fcd0f0db3e8","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0a9fcd0f0db3e8","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0a9fcd0f0db3e8","origin":"seed"}}}'::jsonb, 'published'),
  ('post', 'likya-kayak-konfor-turu', '{"body":{"de":[{"text":"Begleiten Sie uns auf eine Seekajakwoche entlang der Lykischen Küste: Paddeln Sie durch kristallklares Wasser und entdecken Sie antike Städte, versteckte Buchten und in den Fels gehauene lykische Gräber. Nach jedem Abenteuer wartet die türkische Küche.","type":"p"},{"text":"Programm","type":"h2"},{"items":["Tag 1: Empfang am Flughafen und Transfer nach Üçağız; erste Paddeltour um die versunkene Stadt von Kekova und Kaleköy (Simena).","Tag 2: Über die Bucht Tersane zum antiken Aperlai; Schnorcheln über den versunkenen Ruinen und Fischmittagessen in der Bucht Polemos.","Tag 3: Kekova-Ostroute; die Mönchsrobbenhöhle, Meeresschildkröten, das Lykische Museum Andriake und Transfer nach Kaş.","Tag 4: Freier Tag; Bootsausflug nach Kastellorizo, Myra und die Nikolauskirche oder Tauchen in Kaş.","Tag 5: Ein ganzer Kajaktag im Archipel von Kaş mit Mittagessen am Meer.","Tag 6: Von Kalkan zum Strand von Patara paddeln, Picknick am Strand und das antike Patara; Abschiedsessen.","Tag 7: Frühstück und Flughafentransfer."],"type":"ul"},{"text":"Inbegriffen","type":"h2"},{"items":["Gruppentransfers zum Flughafen und alle Landtransporte","6 Hotelübernachtungen","Alle Mahlzeiten und Snacks außer dem Mittagessen am freien Tag","Zertifizierter Kajakguide und zweiter Guide; Begleitboote bei Bedarf","Kajak, Paddel, Schwimmweste, Packsäcke, Spritzdecke und Schnorchelausrüstung","Eintritte für Museen und archäologische Stätten"],"type":"ul"},{"text":"Nicht inbegriffen","type":"h2"},{"items":["Flüge","Persönliche Ausgaben und Trinkgelder","Unterkunft vor und nach der Tour","Optionale Ausflüge am freien Tag","Reiseversicherung"],"type":"ul"},{"text":"Der Gruppentransfer startet am Flughafen Dalaman (DLM); individuell Anreisende können die Gruppe in Üçağız treffen. Aktuelle Preise und Termine auf Anfrage.","type":"p"}],"en":[{"text":"Join our week-long sea kayaking tour along Türkiye''s Lycian Coast: paddle through crystal-clear water and discover ancient cities, hidden coves and Lycian rock-cut tombs. After every adventure, the flavours of Turkish cuisine await.","type":"p"},{"text":"Itinerary","type":"h2"},{"items":["Day 1: Welcome at the airport and transfer to Üçağız; first paddle around the Kekova Sunken City and Kaleköy (Simena).","Day 2: Via Tersane Bay to ancient Aperlai; snorkelling over the sunken ruins and a seafood lunch in Polemos Bay.","Day 3: Kekova east route; the monk seal cave, sea turtles, the Andriake Lycian Museum and transfer to Kaş.","Day 4: Free day; a boat trip to Kastellorizo, Myra and the Church of St Nicholas, or diving in Kaş.","Day 5: A full day of kayaking in the Kaş archipelago with a seaside lunch.","Day 6: Paddle from Kalkan to Patara Beach, a beach picnic and ancient Patara; farewell dinner.","Day 7: Breakfast and airport transfer."],"type":"ul"},{"text":"Included","type":"h2"},{"items":["Group airport transfers and all ground transport","6 nights of hotel accommodation","All meals and snacks except lunch on the free day","Certified kayak guide and second guide; support boats when needed","Kayak, paddle, PFD, dry bags, spraydeck and snorkelling gear","Museum and archaeological site entrance fees"],"type":"ul"},{"text":"Not included","type":"h2"},{"items":["Flights","Personal expenses and tips","Accommodation before and after the tour dates","Optional tours on the free day","Travel insurance"],"type":"ul"},{"text":"The group transfer leaves from Dalaman Airport (DLM); participants arriving independently can meet the group in Üçağız. Please contact us for current prices and dates.","type":"p"}],"fr":[{"text":"Rejoignez notre semaine de kayak de mer le long de la côte lycienne : pagayez dans une eau cristalline et découvrez des cités antiques, des criques cachées et des tombeaux lyciens taillés dans la roche. Après chaque aventure, les saveurs de la cuisine turque vous attendent.","type":"p"},{"text":"Programme","type":"h2"},{"items":["Jour 1 : accueil à l''aéroport et transfert à Üçağız ; première sortie autour de la cité engloutie de Kekova et de Kaleköy (Simena).","Jour 2 : par la baie de Tersane jusqu''à l''antique Aperlai ; snorkeling sur les ruines immergées et déjeuner de fruits de mer dans la baie de Polemos.","Jour 3 : itinéraire est de Kekova ; la grotte des phoques moines, les tortues de mer, le musée lycien d''Andriake et transfert à Kaş.","Jour 4 : journée libre ; excursion en bateau à Kastellorizo, Myra et l''église Saint-Nicolas, ou plongée à Kaş.","Jour 5 : une journée complète de kayak dans l''archipel de Kaş avec déjeuner en bord de mer.","Jour 6 : de Kalkan à la plage de Patara en kayak, pique-nique sur la plage et cité antique de Patara ; dîner d''adieu.","Jour 7 : petit-déjeuner et transfert à l''aéroport."],"type":"ul"},{"text":"Compris","type":"h2"},{"items":["Transferts aéroport en groupe et tous les transports terrestres","6 nuits d''hôtel","Tous les repas et en-cas, sauf le déjeuner du jour libre","Guide kayak certifié et second guide ; bateaux d''assistance si nécessaire","Kayak, pagaie, gilet, sacs étanches, jupe et matériel de snorkeling","Entrées des musées et sites archéologiques"],"type":"ul"},{"text":"Non compris","type":"h2"},{"items":["Vols","Dépenses personnelles et pourboires","Hébergement avant et après les dates du tour","Excursions facultatives du jour libre","Assurance voyage"],"type":"ul"},{"text":"Le transfert de groupe part de l''aéroport de Dalaman (DLM) ; les participants arrivant par leurs propres moyens peuvent rejoindre le groupe à Üçağız. Contactez-nous pour les prix et dates actuels.","type":"p"}],"tr":[{"text":"Türkiye''nin Likya Sahili boyunca haftalık deniz kayağı turumuzda kristal berraklığındaki sularda kürek çekerken antik şehirleri, gizli koyları ve kayalara oyulmuş Likya mezarlarını keşfedin. Her maceranın ardından Türk mutfağının nefis tatları sizi bekliyor.","type":"p"},{"text":"Program","type":"h2"},{"items":["1. gün: Havaalanında karşılama ve Üçağız''a transfer; Kekova Batık Şehri ve Kaleköy (Simena) çevresinde ilk kürek.","2. gün: Tersane Koyu üzerinden Aperlai antik kenti; batık kalıntılarda şnorkel ve Polemos Koyu''nda deniz ürünleriyle öğle yemeği.","3. gün: Kekova doğu rotası; rahip foklarının mağarası, deniz kaplumbağaları, Andriake Likya Müzesi ve Kaş''a transfer.","4. gün: Serbest gün; Meis (Kastellorizo) tekne gezisi, Myra ve Aziz Nikolaos Kilisesi ya da Kaş''ta dalış.","5. gün: Kaş takımadalarında tam gün kayak ve deniz kenarında öğle yemeği.","6. gün: Kalkan''dan Patara Plajı''na kürek, plajda piknik ve Patara Antik Kenti; veda yemeği.","7. gün: Kahvaltı ve havaalanına transfer."],"type":"ul"},{"text":"Dahil olanlar","type":"h2"},{"items":["Grup havaalanı transferleri ve tüm kara ulaşımı","6 gece otel konaklaması","Serbest gündeki öğle yemeği dışında tüm öğünler ve atıştırmalıklar","Sertifikalı kayak rehberi ve ikinci rehber; gerektiğinde destek botları","Kayak, kürek, can yeleği, kuru torba, spraydeck ve şnorkel ekipmanı","Müze ve arkeolojik alan giriş ücretleri"],"type":"ul"},{"text":"Dahil olmayanlar","type":"h2"},{"items":["Uçuşlar","Kişisel harcamalar ve bahşişler","Tur tarihleri dışındaki konaklama","Serbest gündeki isteğe bağlı turlar","Seyahat sigortası"],"type":"ul"},{"text":"Grup transferi Dalaman Havaalanı''ndan (DLM) yapılır; bağımsız gelen katılımcılar grupla Üçağız''da buluşabilir. Güncel fiyat ve tarihler için bizimle iletişime geçin.","type":"p"}]},"cover":"kayak-lycian-comfort-1","date":"2025-05-30","excerpt":{"de":"Eine Woche Seekajak entlang der Lykischen Küste: Kekova, Aperlai, Andriake, Kaş und Patara.","en":"A week-long sea kayaking tour along the Lycian Coast: Kekova, Aperlai, Andriake, Kaş and Patara.","fr":"Une semaine de kayak de mer le long de la côte lycienne : Kekova, Aperlai, Andriake, Kaş et Patara.","tr":"Likya Sahili boyunca haftalık deniz kayağı turu: Kekova, Aperlai, Andriake, Kaş ve Patara."},"id":"likya-kayak-konfor-turu","origin":"cloner","relatedEvents":["likya-kayak-konfor"],"slug":{"de":"lykien-kajak-komfort-tour","en":"lycian-kayak-comfort-escape-tour","fr":"tour-kayak-lycien-evasion-confort","tr":"likya-kayak-ve-konfor-kacamagi-turu"},"sourceRefs":["https://dragoman-turkey.com/tr/dragoman-blog-tr/lycian-kayak-comfort-escape-tour/","1659","590","1658"],"status":"published","title":{"de":"Lykien-Kajak- und Komfort-Tour","en":"Lycian Kayak & Comfort Escape Tour","fr":"Tour kayak lycien et évasion confort","tr":"Likya Kayak ve Konfor Kaçamağı Turu"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1455addc87ceca","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1455addc87ceca","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1455addc87ceca","origin":"seed"}},"/excerpt":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"07442ea0b4a2d8","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"07442ea0b4a2d8","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"07442ea0b4a2d8","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"12104190877941","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"12104190877941","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"12104190877941","origin":"seed"}}}'::jsonb, 'published'),
  ('post', 'maldivler-2026', '{"body":{"de":[{"text":"Das Beste der Malediven – Mittleres Riff: eine Tauchsafari über 8 Tage / 7 Nächte. Einschiffung in Malé am 18. April 2026, Ausschiffung in Malé am 25. April 2026; insgesamt etwa 17 Tauchgänge. Open Water mit mindestens 30 geloggten Tauchgängen erforderlich.","type":"p"},{"text":"Tauchplätze","type":"h2"},{"items":["Nord-Malé-Atoll: Schildkröten, Füsilierschwärme und Graue Riffhaie am Fish Head; ein spektakulärer Kanaltauchgang mit starker Strömung und großen Hochseefischen am Miyaru Kandu.","Süd-Malé-Atoll: Haiaction und manchmal Hammerhaie an der Kandooma Corner; Fischschwärme und gelegentlich Mantas in den Kanälen des Rasdhoo-Atolls.","Ari-Atoll: Ammenhaie und Makrolebewesen bei den berühmten Nachttauchgängen am Maaya Thila; regelmäßige Walhai-Begegnungen an der Dhigurah Corner.","Vaavu-Atoll: Hammerhaie, Mantas und Korallengärten am Fotteyo Kandu; Ammenhaie beim Nachttauchgang am Alimatha Kandu."],"type":"ul"},{"text":"Höhepunkte der Reise","type":"h2"},{"items":["Putzerstationen: Mantas und Haie aus der Nähe beobachten, ohne ihr natürliches Verhalten zu stören.","Makroleben: Nacktschnecken, Garnelen und kleine Rifffische.","Begegnungen mit Hochseefischen: Haischwärme, Adlerrochen und sogar der seltene Hammerhai in Kanälen und an Thilas.","Nachttauchgänge: Ammenhaie und andere nachtaktive Meeresbewohner."],"type":"ul"},{"text":"Das Programm ist flexibel und richtet sich nach den Bedingungen und Sichtungen; der Kapitän kann die Route wegen Wetter, örtlicher Vorschriften oder Logistik ändern. Der letzte Tauchgang findet am vorletzten Tag statt; zwischen dem letzten Tauchgang und dem Flug sollten mindestens 24 Stunden liegen.","type":"p"},{"text":"Inbegriffen","type":"h2"},{"items":["7 Nächte / 8 Tage Vollpension (Divescape Cruiser)","Tauchgänge, Guiding, Nachttauchgänge und Nitrox-Füllungen","TÜRSAB-Pflichtreiseversicherung (bei Abreise aus der Türkei)","MwSt., Treibstoffzuschlag, Nationalpark- und Hafengebühren","Flughafen- und Hoteltransfers","Strand-Barbecue, Landausflüge und Schnorchelguide"],"type":"ul"},{"text":"Nicht inbegriffen","type":"h2"},{"items":["Internationale Flüge und Flughafensteuern","Umweltsteuer und Trinkgeld für die Crew, an Bord zu zahlen","Miete der Tauchausrüstung","Tauchversicherung (DAN-Versicherung ist Pflicht)","Zusätzliche Tauchgänge, Nitrox-Kurs, privater Guide und Tauchkurse"],"type":"ul"}],"en":[{"text":"Best of Maldives – Middle Reef: an 8-day / 7-night liveaboard trip. Embarkation in Malé on 18 April 2026, disembarkation in Malé on 25 April 2026; approximately 17 dives in total. Open Water with a minimum of 30 logged dives required.","type":"p"},{"text":"Dive sites","type":"h2"},{"items":["North Malé Atoll: resident turtles, fusilier schools and grey reef sharks at Fish Head; a dramatic channel dive with strong currents and large pelagics at Miyaru Kandu.","South Malé Atoll: shark action and sometimes hammerheads at Kandooma Corner; schools of fish and occasional manta rays in the channels of Rasdhoo Atoll.","Ari Atoll: nurse sharks and macro critters on the famous night dives at Maaya Thila; consistent whale shark encounters at Dhigurah Corner.","Vaavu Atoll: hammerheads, mantas and coral gardens at Fotteyo Kandu; nurse sharks on the night dive at Alimatha Kandu."],"type":"ul"},{"text":"Itinerary highlights","type":"h2"},{"items":["Cleaning stations: get close to mantas and sharks being groomed without disturbing their natural behaviour.","Macro life: nudibranchs, shrimp and small reef fish.","Pelagic encounters: schools of sharks, eagle rays and even the elusive hammerhead in channels and on pinnacles.","Night dives: nurse sharks and other nocturnal marine life."],"type":"ul"},{"text":"The programme is flexible and follows sea conditions and wildlife sightings; the captain may change the route for weather, local regulations or logistics. The last dive is on the second-to-last day of the trip; waiting at least 24 hours between the last dive and your flight is recommended.","type":"p"},{"text":"Included","type":"h2"},{"items":["7 nights / 8 days full-board accommodation (Divescape Cruiser)","Dives, guiding, night dives and Nitrox fills","TÜRSAB compulsory travel insurance (for departures from Türkiye)","VAT, fuel surcharge, national park and port fees","Airport and hotel transfers","Beach barbecue, land excursions and snorkelling guide"],"type":"ul"},{"text":"Not included","type":"h2"},{"items":["International flights and airport taxes","Green tax and crew tips paid on board","Dive equipment rental","Dive insurance (DAN insurance is compulsory)","Extra dives, Nitrox course, private guide and dive courses"],"type":"ul"}],"fr":[{"text":"Le meilleur des Maldives – Récif central : une croisière plongée de 8 jours / 7 nuits. Embarquement à Malé le 18 avril 2026, débarquement à Malé le 25 avril 2026 ; environ 17 plongées au total. Niveau Open Water avec 30 plongées enregistrées minimum requis.","type":"p"},{"text":"Sites de plongée","type":"h2"},{"items":["Atoll Nord de Malé : tortues résidentes, bancs de fusiliers et requins gris de récif à Fish Head ; plongée spectaculaire en chenal avec de forts courants et de grands pélagiques à Miyaru Kandu.","Atoll Sud de Malé : action requins et parfois requins-marteaux à Kandooma Corner ; bancs de poissons et raies manta occasionnelles dans les chenaux de l''atoll de Rasdhoo.","Atoll Ari : requins nourrices et petites créatures macro lors des célèbres plongées de nuit à Maaya Thila ; rencontres régulières avec les requins-baleines à Dhigurah Corner.","Atoll Vaavu : requins-marteaux, raies manta et jardins coralliens à Fotteyo Kandu ; requins nourrices en plongée de nuit à Alimatha Kandu."],"type":"ul"},{"text":"Points forts de l''itinéraire","type":"h2"},{"items":["Stations de nettoyage : approchez les raies manta et les requins sans perturber leur comportement naturel.","Vie macro : nudibranches, crevettes et petits poissons de récif.","Rencontres pélagiques : bancs de requins, raies aigles et même le discret requin-marteau dans les chenaux et sur les pinacles.","Plongées de nuit : requins nourrices et autres espèces nocturnes."],"type":"ul"},{"text":"Le programme est flexible et s''adapte aux conditions de mer et aux observations ; le capitaine peut modifier l''itinéraire en raison de la météo, de la réglementation locale ou de la logistique. La dernière plongée a lieu l''avant-dernier jour ; il est recommandé d''attendre au moins 24 heures entre la dernière plongée et le vol.","type":"p"},{"text":"Compris","type":"h2"},{"items":["7 nuits / 8 jours en pension complète (Divescape Cruiser)","Plongées, encadrement, plongées de nuit et gonflages Nitrox","Assurance voyage obligatoire TÜRSAB (départs de Turquie)","TVA, surcharge carburant, frais de parc national et de port","Transferts aéroport et hôtel","Barbecue sur la plage, excursions à terre et guide snorkeling"],"type":"ul"},{"text":"Non compris","type":"h2"},{"items":["Vols internationaux et taxes aéroportuaires","Taxe écologique et pourboires de l''équipage payés à bord","Location d''équipement de plongée","Assurance plongée (l''assurance DAN est obligatoire)","Plongées supplémentaires, formation Nitrox, guide privé et cours de plongée"],"type":"ul"}],"tr":[{"text":"Maldivler''in En İyileri – Orta Resif: 8 gün / 7 gecelik canlı tekne (liveaboard) turu. 18 Nisan 2026''da Malé limanından biniş, 25 Nisan 2026''da Malé limanında iniş; toplamda yaklaşık 17 dalış. Open Water ve en az 30 kayıtlı dalış gerekir.","type":"p"},{"text":"Dalış bölgeleri","type":"h2"},{"items":["Kuzey Male Atolü: Fish Head''de yerleşik kaplumbağalar, fusilier sürüleri ve gri resif köpekbalıkları; Miyaru Kandu''da güçlü akıntılı kanal dalışı ve büyük pelajikler.","Güney Male Atolü: Kandooma Corner''da köpekbalığı hareketi ve zaman zaman çekiçbaşlar; Rasdhoo Atolü kanallarında balık sürüleri ve manta vatozları.","Ari Atolü: gece dalışlarıyla ünlü Maaya Thila''da hemşire köpekbalıkları ve makro canlılar; Dhigurah Corner''da balina köpekbalıkları.","Vaavu Atolü: Fotteyo Kandu''da çekiçbaşlar, mantalar ve mercan bahçeleri; Alimatha Kandu''da gece dalışında hemşire köpekbalıkları."],"type":"ul"},{"text":"Turun öne çıkanları","type":"h2"},{"items":["Temizlik istasyonları: manta vatozları ve köpekbalıklarını doğal davranışlarını bozmadan yakından izleme.","Makro yaşam: deniz tavşanları (nudibranch), karidesler ve küçük resif balıkları.","Pelajik karşılaşmalar: kanallarda ve thila''larda köpekbalığı sürüleri, kartal vatozları ve nadiren çekiçbaş köpekbalıkları.","Gece dalışları: hemşire köpekbalıkları ve gececi deniz canlıları."],"type":"ul"},{"text":"Program deniz koşullarına ve canlı gözlemlerine göre esnektir; güzergâh hava koşulları, yerel düzenlemeler ve lojistik nedenlerle kaptan tarafından değiştirilebilir. Son dalış, turun sondan bir önceki gününde yapılır; son dalıştan sonra uçuşa kadar en az 24 saat beklenmesi tavsiye edilir.","type":"p"},{"text":"Dahil olanlar","type":"h2"},{"items":["7 gece 8 gün tam pansiyon konaklama (Divescape Cruiser)","Dalışlar, rehberlik, gece dalışları ve nitrox dolumları","TÜRSAB zorunlu seyahat sigortası (Türkiye çıkışlılar için)","KDV, yakıt farkı, milli park ve liman ücretleri","Havalimanı ve otel transferleri","Plaj barbeküsü, karasal geziler ve şnorkel rehberi"],"type":"ul"},{"text":"Dahil olmayanlar","type":"h2"},{"items":["Uluslararası uçuşlar ve havalimanı vergileri","Teknede ödenen yeşil vergi ve tekne bahşişi","Dalış ekipmanı kiralama","Dalış sigortası (DAN sigortası zorunludur)","Ekstra dalışlar, nitrox kursu, özel rehber ve dalış kursları"],"type":"ul"}]},"cover":"blog-maldives","date":"2025-05-31","excerpt":{"de":"18.–25. April 2026: das Beste der Malediven an Bord der Divescape Cruiser, insgesamt etwa 17 Tauchgänge.","en":"18–25 April 2026: the best of the Maldives aboard the Divescape Cruiser, about 17 dives in total.","fr":"18–25 avril 2026 : le meilleur des Maldives à bord du Divescape Cruiser, environ 17 plongées au total.","tr":"18–25 Nisan 2026: Divescape Cruiser ile Maldivler''in en iyileri, toplam yaklaşık 17 dalış."},"id":"maldivler-2026","origin":"cloner","relatedEvents":[],"slug":{"de":"tauchreise-malediven-2026","en":"maldives-diving-trip-2026","fr":"voyage-plongee-maldives-2026","tr":"maldivler-dalis-turu-2026"},"sourceRefs":["https://dragoman-turkey.com/tr/dragoman-blog-tr/dragoman-maldives-diving-trip-2026/","848","667","922"],"status":"published","title":{"de":"Dragoman-Tauchreise Malediven 2026","en":"Dragoman Maldives Diving Trip 2026","fr":"Voyage plongée Dragoman aux Maldives 2026","tr":"Dragoman Maldivler Dalış Turu 2026"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0430b9ad04117b","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0430b9ad04117b","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0430b9ad04117b","origin":"seed"}},"/excerpt":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1b995976d227a3","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1b995976d227a3","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1b995976d227a3","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1b1b8c488fa685","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1b1b8c488fa685","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1b1b8c488fa685","origin":"seed"}}}'::jsonb, 'published'),
  ('post', 'raja-ampat-2027', '{"body":{"de":[{"text":"Raja Ampat liegt nordwestlich der Insel Neuguinea und ist ein Archipel im Herzen des Korallendreiecks, das oft als Wiege der weltweiten Korallenvielfalt bezeichnet wird. Mit über 500 Korallen- und mehr als 1.000 Fischarten bietet dieses berühmte Meeresschutzgebiet eine der reichsten Unterwasserwelten der Erde.","type":"p"},{"text":"Das Programm umfasst drei Bootstauchgänge pro Tag, danach unbegrenzte Tauchgänge am Hausriff des Resorts, auch nachts. Mit Nitrox-Brevet ist Nitrox kostenlos; ohne Brevet kann Dragoman vorab einen Nitrox-Kurs ohne Tauchgänge organisieren. Auch Nichttaucher können Naturausflüge auf See und an Land unternehmen.","type":"p"},{"text":"Unter Wasser","type":"h2"},{"text":"Unberührte Korallenwälder, Füsilierschwärme in leuchtenden Farben, dichte Glasfischwolken, riesige Mantas an Putzerstationen von Falterfischen, Wobbegongs, Krokodilfische und beim Nachttauchgang vor dem Resort die scheuen Mandarinfische. Der Tauchausflug nach Wayag ist ein Muss.","type":"p"},{"text":"Inbegriffen","type":"h2"},{"items":["Vollpension im Resort (7 Nächte)","Bootstransfer Sorong – Resort – Sorong","Unbegrenztes Tauchen (3 Bootstauchgänge pro Tag), Luft- und Nitroxflaschen, Blei","TÜRSAB-Reisegarantieversicherung"],"type":"ul"},{"text":"Flüge buchen die Teilnehmenden selbst. Eine DAN-Tauchversicherung ist Pflicht.","type":"p"}],"en":[{"text":"Located northwest of the island of New Guinea, Raja Ampat is an archipelago in the heart of the Coral Triangle, often described as the cradle of the world''s coral biodiversity. With more than 500 species of coral and over 1,000 species of fish, this world-famous marine sanctuary offers one of the richest underwater worlds on the planet.","type":"p"},{"text":"The programme includes three boat dives per day, followed by unlimited dives from the resort''s house reef, including night dives. If you are Nitrox certified, Nitrox is free of charge; if not, Dragoman can arrange a non-diving certification programme beforehand. Non-divers can enjoy nature excursions at sea and on land.","type":"p"},{"text":"What''s underwater?","type":"h2"},{"text":"Pristine coral forests, fusilier schools in dazzling colours, dense clouds of glassfish, giant mantas being cleaned by butterflyfish, wobbegongs, crocodilefish and, on the night dive in front of the resort, shy mandarin fish. The dive trip to Wayag is a must.","type":"p"},{"text":"Included","type":"h2"},{"items":["Full-board accommodation at the resort (7 nights)","Sorong – resort – Sorong boat transfer","Unlimited diving (3 boat dives a day), air and Nitrox tanks, weights","TÜRSAB travel guarantee insurance"],"type":"ul"},{"text":"Participants book their own flights. DAN dive insurance is compulsory.","type":"p"}],"fr":[{"text":"Situé au nord-ouest de l''île de Nouvelle-Guinée, Raja Ampat est un archipel au cœur du Triangle de Corail, souvent considéré comme le berceau de la biodiversité corallienne mondiale. Avec plus de 500 espèces de coraux et plus de 1 000 espèces de poissons, ce sanctuaire marin offre l''un des univers sous-marins les plus riches de la planète.","type":"p"},{"text":"Le programme comprend trois plongées en bateau par jour, puis des plongées illimitées sur le récif du resort, y compris de nuit. Si vous êtes certifié Nitrox, le Nitrox est gratuit ; sinon, Dragoman peut organiser une formation Nitrox sans plongée avant le voyage. Les non-plongeurs peuvent profiter d''excursions nature en mer et sur terre.","type":"p"},{"text":"Sous l''eau","type":"h2"},{"text":"Des forêts de coraux intactes, des bancs de fusiliers aux couleurs éclatantes, des nuages de poissons de verre, des raies manta géantes nettoyées par des poissons-papillons, des wobbegongs, des poissons-crocodiles et, en plongée de nuit devant le resort, les timides poissons-mandarins. La sortie à Wayag est incontournable.","type":"p"},{"text":"Compris dans le prix","type":"h2"},{"items":["Pension complète au resort (7 nuits)","Transfert en bateau Sorong – resort – Sorong","Plongée illimitée (3 plongées bateau par jour), bouteilles air et Nitrox, plombs","Assurance garantie voyage TÜRSAB"],"type":"ul"},{"text":"Les participants réservent eux-mêmes leurs vols. L''assurance plongée DAN est obligatoire.","type":"p"}],"tr":[{"text":"Raja Ampat, Papua Yeni Gine adasının kuzeybatısında, dünya mercanlarının yayılma noktası olduğu düşünüldüğünden “Altın Üçgen” adı verilen bölgedeki bir adalar grubu. 500''ü aşkın mercan ve 1000''i aşkın balık türü barındıran dünyaca ünlü bir deniz koruma alanı.","type":"p"},{"text":"Günde tekneyle 3 dalış yapılıyor, ardından resort önünden dalışlar (ve gece dalışı) istediğiniz kadar. Nitrox bröveniz varsa nitrox ücretsiz; yoksa öncesinde dalışsız bir programla Dragoman brövenizi almanızı sağlayabilir. Dalmayanlar için de deniz ve kara odaklı doğa gezileri öneriliyor.","type":"p"},{"text":"Sualtında neler var?","type":"h2"},{"text":"El değmemiş mercan ormanları, renk renk füzelier sürüleri, yoğun glassfish bulutları, kelebek balıklarının temizlediği dev mantalar, wobegong''lar, timsah balıkları ve resort önündeki gece dalışında çekingen mandarin balıkları. Dalışlı Wayag gezisi de mutlaka yapılmalı.","type":"p"},{"text":"Fiyata dahil olanlar","type":"h2"},{"items":["Resort''ta tam pansiyon konaklama (7 gece)","Sorong – resort – Sorong tekne transferi","Sınırsız dalış (tekneyle günde 3 dalış), hava ve nitrox tüpleri, ağırlık","TÜRSAB Seyahat Güvence Sigortası"],"type":"ul"},{"text":"Uçak biletleri katılımcılar tarafından alınır. DAN dalış sigortası zorunludur.","type":"p"}]},"cover":"blog-raja-ampat-2027","date":"2026-03-07","excerpt":{"de":"Eine Dragoman-Tauchreise in das Meeresschutzgebiet mit über 500 Korallen- und mehr als 1.000 Fischarten.","en":"A Dragoman dive trip to the marine sanctuary known for more than 500 coral and over 1,000 fish species.","fr":"Un voyage plongée Dragoman dans le sanctuaire marin connu pour ses plus de 500 espèces de coraux et 1 000 espèces de poissons.","tr":"500''ü aşkın mercan ve 1000''i aşkın balık türüyle ünlü deniz koruma alanına Dragoman dalış gezisi."},"id":"raja-ampat-2027","origin":"cloner","relatedEvents":[],"seo":{"description":{"de":"Mit Dragoman nach Raja Ampat, 18.–27. Dezember 2027: über 500 Korallen- und 1.000 Fischarten im Korallendreieck, drei Bootstauchgänge täglich plus Hausriff.","en":"Dive Raja Ampat with Dragoman, 18–27 December 2027: over 500 coral and 1,000 fish species, three boat dives a day plus unlimited house-reef dives.","fr":"Avec Dragoman à Raja Ampat du 18 au 27 décembre 2027 : plus de 500 coraux et 1 000 espèces de poissons, trois plongées bateau par jour et le récif à volonté.","tr":"18–27 Aralık 2027''de Raja Ampat''a Dragoman dalış gezisi: Mercan Üçgeni''nde 500''ü aşkın mercan ve 1000''i aşkın balık türü, günde üç tekne dalışı ve ev resifi."},"title":{"de":"Tauchreise Raja Ampat, 18.–27. Dezember 2027","en":"Raja Ampat Dive Trip, 18–27 December 2027","fr":"Voyage plongée à Raja Ampat, 18–27 décembre 2027","tr":"Raja Ampat 2027: 18–27 Aralık Dalış Gezisi"}},"slug":{"de":"raja-ampat-2027","en":"raja-ampat-2027","fr":"raja-ampat-2027","tr":"raja-ampat-2027"},"sourceRefs":["https://dragoman-turkey.com/tr/dragoman-blog-tr/raja-ampat-2027/","1884","2217","2233"],"status":"published","title":{"de":"Wir fahren wieder nach Raja Ampat, 18.–27. Dezember 2027","en":"We are heading back to Raja Ampat, 18–27 December 2027","fr":"Nous retournons à Raja Ampat, du 18 au 27 décembre 2027","tr":"Raja Ampat''a 2027 Noel tarihlerinde (18–27 Aralık) tekrar gidiyoruz"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0a15078e17d109","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0a15078e17d109","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0a15078e17d109","origin":"seed"}},"/excerpt":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"058eee1579cb43","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"058eee1579cb43","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"058eee1579cb43","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1c70f38f76110d","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1c70f38f76110d","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1c70f38f76110d","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0ee3236870cc9e","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0ee3236870cc9e","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0ee3236870cc9e","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"130b9d0e912e55","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"130b9d0e912e55","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"130b9d0e912e55","origin":"seed"}}}'::jsonb, 'published'),
  ('post', 'sharm-el-sheikh-2026', '{"body":{"de":[{"text":"Auf dieser Reise von 8 Tagen / 7 Nächten machen wir vom 26. bis 29. Oktober etwa 10 Tauchgänge: je drei in den Gebieten Tiran und Ras Mohammed und für Interessierte die Thistlegorm. Der 30. Oktober ist Ruhe- oder freier Tag. Mindestens Open-Water-Brevet erforderlich.","type":"p"}],"en":[{"text":"On this 8-day / 7-night trip we make about 10 dives on 26–29 October: three dives each in the Tiran and Ras Mohammed areas, and the Thistlegorm for those who wish. 30 October is a rest or free day. Minimum Open Water certification required.","type":"p"}],"fr":[{"text":"Pendant ce voyage de 8 jours / 7 nuits, nous faisons une dizaine de plongées du 26 au 29 octobre : trois plongées dans chacun des secteurs de Tiran et de Ras Mohammed, et le Thistlegorm pour ceux qui le souhaitent. Le 30 octobre est une journée de repos ou libre. Niveau Open Water minimum.","type":"p"}],"tr":[{"text":"8 gün / 7 gecelik gezide 26–29 Ekim günlerinde toplam yaklaşık 10 dalış yapıyoruz: Tiran ve Ras Muhammed bölgelerinde 3''er dalış, isteyenler için Thistlegorm. 30 Ekim dinlenme ya da serbest gün. En az Open Water sertifikası gerekir.","type":"p"}]},"cover":"blog-sharm-el-sheikh","date":"2026-06-13","excerpt":{"de":"25.–31. Oktober 2026: Tiran, Ras Mohammed und die Thistlegorm.","en":"25–31 October 2026: Tiran, Ras Mohammed and the Thistlegorm.","fr":"25–31 octobre 2026 : Tiran, Ras Mohammed et le Thistlegorm.","tr":"25–31 Ekim 2026: Tiran, Ras Muhammed ve Thistlegorm."},"id":"sharm-el-sheikh-2026","origin":"cloner","relatedEvents":[],"seo":{"description":{"de":"8 Tage und 7 Nächte in Sharm El Sheikh, 25.–31. Oktober 2026: rund 10 Tauchgänge bei Tiran und Ras Mohammed, optional die Thistlegorm. Mindestens Open Water.","en":"Eight days and seven nights in Sharm El Sheikh, 25–31 October 2026: about 10 dives at Tiran and Ras Mohammed, plus the Thistlegorm wreck. Open Water minimum.","fr":"8 jours et 7 nuits à Sharm El Sheikh du 25 au 31 octobre 2026 : une dizaine de plongées à Tiran et Ras Mohammed, Thistlegorm en option. Open Water minimum.","tr":"25–31 Ekim 2026''da 8 gün 7 gece Sharm El Sheikh: Tiran ve Ras Muhammed''de yaklaşık 10 dalış, isteyene Thistlegorm batığı. En az Open Water sertifikası gerekir."},"title":{"de":"Tauchreise Sharm El Sheikh, 25.–31. Oktober 2026","en":"Sharm El Sheikh Dive Trip, 25–31 October 2026","fr":"Plongée à Sharm El Sheikh, 25–31 octobre 2026","tr":"Sharm El Sheikh Dalış Turu: 25–31 Ekim 2026"}},"slug":{"de":"tauchreise-sharm-el-sheikh-2026","en":"sharm-el-sheikh-dive-trip-2026","fr":"voyage-plongee-sharm-el-sheikh-2026","tr":"sharm-el-sheikh-dalis-turu-2026"},"sourceRefs":["https://dragoman-turkey.com/tr/dragoman-blog/dragoman-sharm-el-sheikh-dalis-turu-2026/","1987"],"status":"published","title":{"de":"Dragoman-Tauchreise Sharm El Sheikh 2026","en":"Dragoman Sharm El Sheikh Dive Trip 2026","fr":"Voyage plongée Dragoman à Sharm El Sheikh 2026","tr":"Dragoman Sharm El Sheikh Dalış Turu 2026"},"translationOrigin":{"de":"mockup","en":"mockup","fr":"mockup"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0ec75129c554d0","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0ec75129c554d0","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0ec75129c554d0","origin":"seed"}},"/excerpt":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"00ceea7ba6ecd4","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"00ceea7ba6ecd4","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"00ceea7ba6ecd4","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"047d050ec3f7c7","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"047d050ec3f7c7","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"047d050ec3f7c7","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"000a5aeaab2cff","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"000a5aeaab2cff","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"000a5aeaab2cff","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0b3805206c63e8","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0b3805206c63e8","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0b3805206c63e8","origin":"seed"}}}'::jsonb, 'published'),
  ('post', 'web-semineri-kas', '{"body":{"de":[{"text":"Die Aufzeichnung unseres Webinars vom Sommer 2021 ist jetzt online! Wie wäre es mit Ihrem nächsten Urlaub in Kaş?","type":"p"},{"items":["Kaş, die Perle Lykiens: eine antike Stadt der lykischen Zivilisation","Ein alter Hafen und eine Marina gegenüber der griechischen Insel Meis (Kastellorizo)","Kekova, eine weitere, versunkene antike Stadt","Ein Ziel für viele Sportarten: Seekajak, Wandern, Mountainbiken, Coasteering und vor allem Tauchen","Ein reiches Unterwasser-Kulturerbe und vielfältiges Meeresleben (Arten aus dem Roten Meer)"],"type":"ul"}],"en":[{"text":"The recording of our summer 2021 webinar is now online! How about booking your next holiday in Kaş?","type":"p"},{"items":["Kaş, the pearl of Lycia: an ancient city of the Lycian civilization","An old port and marina facing the Greek island of Meis (Kastellorizo)","Kekova, another ancient city, submerged","A multi-sport destination: sea kayaking, hiking, mountain biking, coasteering and especially diving","A rich underwater cultural heritage and abundant marine life (species coming from the Red Sea)"],"type":"ul"}],"fr":[{"text":"Le replay de notre webinaire de l''été 2021 est en ligne ! Et si vous réserviez vos prochaines vacances à Kaş ?","type":"p"},{"items":["Kaş, perle de la Lycie : une cité antique de la civilisation lycienne","Un vieux port et une marina face à l''île grecque de Meis (Kastellorizo)","Kekova, une autre cité antique submergée","Une destination multisports : kayak de mer, VTT, coasteering et plongée","Un riche patrimoine culturel subaquatique et une vie marine foisonnante (espèces venues de la mer Rouge)"],"type":"ul"}],"tr":[{"text":"2021 yazında gerçekleştirdiğimiz web seminerinin kaydı artık çevrim içi! Bir sonraki tatilinizi Kaş''ta geçirmeye ne dersiniz?","type":"p"},{"items":["Likya''nın incisi Kaş: Likya uygarlığının antik bir kenti","Yunan adası Meis''e (Kastellorizo) bakan eski bir liman ve marina","Kekova, sular altında kalmış bir başka antik kent","Çok yönlü bir spor destinasyonu: deniz kayağı, yürüyüş, dağ bisikleti, coasteering ve özellikle dalış","Zengin sualtı kültürel mirası ve bol deniz yaşamı (Kızıldeniz''den gelen türler)"],"type":"ul"}]},"cover":"blog-webinar-kas","date":"2026-01-13","excerpt":{"de":"Die Aufzeichnung unseres Webinars vom Sommer 2021 über Kaş, Kekova und das Unterwassererbe von Kaş.","en":"The recording of our summer 2021 webinar on Kaş, Kekova and the underwater heritage of Kaş.","fr":"L''enregistrement de notre webinaire de l''été 2021 sur Kaş, Kekova et le patrimoine sous-marin de Kaş.","tr":"Kaş, Kekova ve Kaş''ın sualtı mirası üzerine 2021 yazında yapılan web seminerinin kaydı."},"id":"web-semineri-kas","origin":"cloner","relatedEvents":[],"seo":{"description":{"de":"Die Aufzeichnung des Webinars vom Sommer 2021 ist online: Kaş, die Perle Lykiens, die versunkene Stadt Kekova, ein Multisport-Ziel, reiches Unterwassererbe.","en":"Our summer 2021 webinar recording is online: Kaş, the pearl of Lycia, the sunken city of Kekova, a multi-sport destination and its underwater heritage.","fr":"Le replay du webinaire de l''été 2021 est en ligne : Kaş, perle lycienne, Kekova et sa cité engloutie, destination multisport, riche patrimoine sous-marin.","tr":"2021 yazında yaptığımız web seminerinin kaydı çevrim içi: Likya''nın incisi Kaş, batık antik kent Kekova, çok sporlu bir tatil ve Kaş''ın zengin sualtı mirası."},"title":{"de":"Webinar-Aufzeichnung: Diesen Sommer nach Kaş?","en":"Webinar Replay: Come (Back) to Kaş This Summer","fr":"Replay du webinaire : (re)venir à Kaş cet été","tr":"Web Semineri Kaydı: Bu Yaz Kaş''a (Yeniden) Gelin"}},"slug":{"de":"kas-webinar-aufzeichnung","en":"kas-webinar-replay","fr":"replay-webinaire-kas","tr":"kas-web-semineri-kaydi"},"sourceRefs":["https://dragoman-turkey.com/tr/dragoman-blog-tr/the-replay-of-the-webinar-and-if-you-came-back-to-kas-this-summer-is-now-online/","1799","1792","1798"],"status":"published","title":{"de":"Die Aufzeichnung des Webinars „Und wenn Sie diesen Sommer (wieder) nach Kaş kämen?“ ist online","en":"The replay of the webinar “And if you came (back) to Kaş this summer?” is online","fr":"Le replay du webinaire « Et si vous (re)veniez à Kaş cet été ? » est en ligne","tr":"“Bu yaz Kaş''a (yeniden) gelmeye ne dersiniz?” web seminerinin kaydı çevrim içi"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1670454a66476c","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1670454a66476c","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1670454a66476c","origin":"seed"}},"/excerpt":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"09cf7b48fe0093","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"09cf7b48fe0093","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"09cf7b48fe0093","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0748b333ffdf6b","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0748b333ffdf6b","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0748b333ffdf6b","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0f2c6795b843de","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0f2c6795b843de","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0f2c6795b843de","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"14fecc478d68c6","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"14fecc478d68c6","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"14fecc478d68c6","origin":"seed"}}}'::jsonb, 'published'),
  ('product', 'the-diving-guide-kas', '{"body":{"de":[{"text":"Der Führer vereint Unterwasserkarten, die das Dragoman-Team über Jahre aus topografischen Notizen bei seinen Tauchgängen zusammengestellt hat, eine Einführung in die Region und den Druck auf ihre Tier- und Pflanzenwelt sowie Fotos aller Arten, die wir dokumentieren konnten.","type":"p"},{"text":"Die erweiterte 3. Auflage wächst von 200 auf 352 Seiten, von 429 auf 715 Fotos und von 200 auf 307 Arten. Nach Türkisch, Englisch, Französisch und Deutsch kam Russisch als fünfte Sprache hinzu. Zwei nach 2012 versenkte Wracks, der Panzer und das Boot Altuğ, sind jetzt auf den Karten eingetragen.","type":"p"},{"text":"Wer die Karten nutzt, sollte sie nicht als einzige Grundlage nehmen und sich auf seine Tauchguides verlassen.","type":"p"}],"en":[{"text":"Accessible only by boat even in the fifties, Kaş has remained one of the unspoilt corners of the Mediterranean. The book brings together underwater maps compiled from the Dragoman team''s topographic notes over years of diving, an introduction to the area and the pressures on its fauna and flora, and photographs of the species we have been able to document.","type":"p"},{"text":"The expanded 3rd edition grows from 200 to 352 pages, from 429 to 715 photographs and from 200 to 307 species. After Turkish, English, French and German, Russian has been added as a fifth language. Two new wrecks sunk after 2012, the Tank and the Altuğ boat, are now on the maps.","type":"p"},{"text":"Divers using the maps should not take them as their only reference and should trust their dive guides.","type":"p"}],"fr":[{"text":"Ce guide réunit les cartes sous-marines établies à partir des notes topographiques prises par l''équipe Dragoman au fil des années de plongée, une présentation de la région et des pressions qui pèsent sur sa faune et sa flore, et les photos des espèces que nous avons pu documenter.","type":"p"},{"text":"La 3e édition augmentée passe de 200 à 352 pages, de 429 à 715 photos et de 200 à 307 espèces. Après le turc, l''anglais, le français et l''allemand, le russe a été ajouté comme cinquième langue. Deux nouvelles épaves coulées après 2012, le Tank et le bateau Altuğ, figurent désormais sur les cartes.","type":"p"},{"text":"Les plongeurs qui utilisent les cartes ne doivent pas en faire leur seule référence et doivent faire confiance à leurs guides.","type":"p"}],"tr":[{"text":"Dragoman ekibi olarak yıllardır dalışlarımızda aldığımız topografik notlardan sualtı haritalarını yeniden derledik ve eksikleri tamamladık. Kitabın başındaki bölümler bölgenin özelliklerini ve fauna ile flora üzerindeki baskıları özetliyor; biyolojik çeşitliliği yansıtmak için fotoğraflayabildiğimiz her canlıya yer verdik.","type":"p"},{"text":"Genişletilmiş 3. baskıda 2. baskıdaki 200 sayfadan 352 sayfaya, 429 fotoğraftan 715 fotoğrafa, 200 canlı türünden 307''ye ulaştık. Türkçe, İngilizce, Fransızca ve Almanca''nın ardından 5. dil olarak Rusça eklendi. 2012''den sonra batırılan iki yeni batık, Tank ve Altuğ teknesi de haritalara işlendi.","type":"p"},{"text":"Haritalardan yararlanan dalıcılar lütfen onları tek referans olarak almasın ve dalış rehberlerine güvensin.","type":"p"}]},"cover":"book-diving-guide-kas","currency":"EUR","edition":{"de":"Erweiterte 3. Auflage, in 5 Sprachen","en":"Expanded 3rd edition, in 5 languages","fr":"3e édition augmentée, en 5 langues","tr":"Genişletilmiş 3. baskı, 5 dilde"},"gallery":["diving-turtle-2","diving-sea-urchin-1","dive-sites-kas-map-1"],"id":"the-diving-guide-kas","order":1,"origin":"cloner","price":30,"priceVerified":false,"seo":{"description":{"de":"Unterwasserkarten der Tauchplätze von Kaş, 307 Arten und 715 Fotos: die erweiterte 3. Auflage des Dragoman-Tauchführers, 352 Seiten in 5 Sprachen.","en":"Detailed underwater maps of the Kaş dive sites, 307 species and 715 photos: the expanded 3rd edition of the Dragoman team''s guide, 352 pages in 5 languages.","fr":"Cartes sous-marines des sites de plongée de Kaş, 307 espèces et 715 photos : la 3e édition augmentée du guide de l''équipe Dragoman, 352 pages, 5 langues.","tr":"Kaş dalış noktalarının ayrıntılı sualtı haritaları, 307 tür ve 715 fotoğraf: Dragoman ekibinin rehberinin genişletilmiş 3. baskısı, 352 sayfa ve 5 dilde."},"title":{"de":"Tauchführer Kaş: Tauchplatzkarten und 307 Arten","en":"The Diving Guide – Kaş: Maps and 307 Species","fr":"Guide de plongée – Kaş : cartes et 307 espèces","tr":"Dalış Rehberi – Kaş: Sualtı Haritaları ve 307 Tür"}},"slug":{"de":"tauchfuehrer-kas","en":"the-diving-guide-kas","fr":"guide-de-plongee-kas","tr":"dalis-rehberi-kas"},"sourceRefs":["https://dragoman-turkey.com/tr/urun/dalis-rehberi-kas/","https://dragoman-turkey.com/product/the-diving-guide-kas/","165","15"],"status":"published","summary":{"de":"Detaillierte Unterwasserkarten der Tauchplätze von Kaş und 307 Arten auf 352 Seiten.","en":"Detailed underwater maps of the Kaş dive sites and 307 species, on 352 pages.","fr":"Cartes sous-marines détaillées des sites de Kaş et 307 espèces, sur 352 pages.","tr":"Kaş dalış noktalarının ayrıntılı sualtı haritaları ve 307 canlı türü, 352 sayfada."},"title":{"de":"The Diving Guide – Kaş","en":"The Diving Guide – Kaş","fr":"The Diving Guide – Kaş","tr":"Dalış Rehberi – Kaş"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"mockup"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0980115b8fb1a5","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0980115b8fb1a5","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0980115b8fb1a5","origin":"seed"}},"/edition":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1b2f3357c11273","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1b2f3357c11273","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1b2f3357c11273","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"105de737a64b79","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"105de737a64b79","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"105de737a64b79","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"173fba74db6bd8","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"173fba74db6bd8","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"173fba74db6bd8","origin":"seed"}},"/summary":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1eeef32cb50c1a","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1eeef32cb50c1a","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1eeef32cb50c1a","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"14aa8ac3a04f7c","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"14aa8ac3a04f7c","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"14aa8ac3a04f7c","origin":"seed"}}}'::jsonb, 'published'),
  ('product', 'tropical-mediterranean-english', '{"body":{"de":[{"text":"Das Mittelmeer erlebt die volle Wirkung eingewanderter Arten, von denen manche rasch invasiv werden. Besonders das östliche Mittelmeer ist direkt von Arten betroffen, die durch den Suezkanal kommen, ein Phänomen, das als lessepsische Migration bekannt ist. Wir beobachten seine Folgen für die marine Artenvielfalt mit Faszination und Sorge zugleich.","type":"p"},{"text":"Dieses Buch erhebt keinen Anspruch auf Wissenschaftlichkeit oder Vollständigkeit. Es zeigt in ästhetischer Herangehensweise exotische Meeresarten, die zwischen 2000 und 2024 in der Region Kaş beobachtet wurden. In dieser zweiten, erweiterten Auflage (die erste hieß „Red Sea in the Med“) werden 76 Arten mit mehr als 200 Fotos und kurzen Kommentaren vorgestellt, dazu 31 Amateurvideos über QR-Codes.","type":"p"}],"en":[{"text":"The Mediterranean is experiencing the full impact of exotic species, some of which are rapidly becoming invasive. At the forefront, the Eastern Mediterranean is directly affected by species arriving through the Suez Canal, a phenomenon known as Lessepsian migration. We closely observe its effects on marine biodiversity, torn between fascination and concern.","type":"p"},{"text":"This book does not claim to be scientific or exhaustive. It offers an aesthetic approach based on observations of exotic marine species in the Kaş region between 2000 and 2024. In this second expanded edition (the first edition was called “Red Sea in the Med”), 76 species are presented through more than 200 photographs with concise commentary, plus 31 amateur videos accessible via QR codes.","type":"p"}],"fr":[{"text":"La Méditerranée subit de plein fouet l''impact des espèces exotiques, dont certaines deviennent rapidement invasives. En première ligne, la Méditerranée orientale est directement affectée par les espèces venues par le canal de Suez, un phénomène connu sous le nom de migration lessepsienne. Nous en observons les effets sur la biodiversité marine, partagés entre fascination et inquiétude.","type":"p"},{"text":"Ce livre n''a pas la prétention d''être un ouvrage scientifique ou exhaustif. Il propose une approche esthétique, à travers des observations d''espèces marines exotiques dans la région de Kaş entre 2000 et 2024. Dans cette 2e édition augmentée (la première s''intitulait « Red Sea in the Med »), 76 espèces sont présentées au fil de plus de 200 photos accompagnées de commentaires concis, ainsi que 31 vidéos amateurs accessibles par codes QR.","type":"p"}],"tr":[{"text":"Akdeniz, bazıları hızla istilacı hale gelen göçmen türlerin etkisini tam anlamıyla yaşamaktadır. Özellikle Doğu Akdeniz, Süveyş Kanalı yoluyla gelen bu türlerden doğrudan etkilenmektedir. Lesepsiyen göçü denen bu olgunun deniz biyolojik çeşitliliği üzerindeki etkilerini hem hayranlık hem de endişeyle yakından gözlemliyoruz.","type":"p"},{"text":"Bu kitap bilimsellik ya da bütünlük iddiasından çok estetik bir yaklaşımla, 2000 ile 2024 yılları arasında Kaş bölgesinde gözlemlenen egzotik deniz türlerini sunuyor. İlk baskısı “Akdeniz''de Kızıldeniz – Red Sea in the Med” adını taşıyan bu ikinci genişletilmiş baskıda 76 tür, 200''den fazla fotoğraf ve kısa yorumlarla anlatılıyor; karekodlarla erişilebilen 31 amatör video da eklendi.","type":"p"}]},"cover":"book-tropical-mediterranean-en","currency":"EUR","edition":{"de":"Englische Ausgabe","en":"English edition","fr":"Édition anglaise","tr":"İngilizce baskı"},"gallery":["book-tropical-spread-1","book-tropical-spread-2","book-tropical-spread-3","book-tropical-spread-4"],"id":"tropical-mediterranean-english","order":2,"origin":"cloner","price":39,"priceVerified":false,"seo":{"description":{"de":"76 exotische Meeresarten aus dem Roten Meer, beobachtet in Kaş zwischen 2000 und 2024, in über 200 Fotos. Die erweiterte zweite Auflage auf Englisch.","en":"76 exotic marine species from the Red Sea, observed in Kaş between 2000 and 2024, in more than 200 photographs. The expanded second edition, in English.","fr":"76 espèces marines exotiques venues de la mer Rouge, observées à Kaş entre 2000 et 2024, en plus de 200 photos. Deuxième édition augmentée, en anglais.","tr":"Kaş''ta 2000–2024 arasında gözlemlenen ve Kızıldeniz''den gelen 76 egzotik deniz türü, 200''ü aşkın fotoğrafla. Genişletilmiş 2. baskı, İngilizce."},"title":{"de":"Tropical Mediterranean – englische Ausgabe","en":"Tropical Mediterranean – English Edition","fr":"Tropical Mediterranean – édition anglaise","tr":"Tropical Mediterranean: İngilizce Baskı, 76 Tür"}},"slug":{"de":"tropisches-mittelmeer-englisch","en":"tropical-mediterranean-english","fr":"mediterranee-tropicale-anglais","tr":"tropikal-akdeniz-ingilizce"},"sourceRefs":["products.csv","https://dragoman-turkey.com/tr/urun/tropikal-akdeniz-ingilizce/","https://dragoman-turkey.com/product/tropical-mediterranean-english/","162","41","995"],"status":"published","summary":{"de":"76 exotische Meeresarten aus dem Roten Meer, beobachtet in Kaş zwischen 2000 und 2024.","en":"76 exotic marine species from the Red Sea, observed in Kaş between 2000 and 2024.","fr":"76 espèces marines exotiques venues de la mer Rouge, observées à Kaş entre 2000 et 2024.","tr":"Kaş''ta 2000–2024 arasında gözlemlenen, Kızıldeniz''den gelen 76 egzotik deniz türü."},"title":{"de":"Tropical Mediterranean","en":"Tropical Mediterranean","fr":"Tropical Mediterranean","tr":"Tropical Mediterranean"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0bae62f9909eb5","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0bae62f9909eb5","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0bae62f9909eb5","origin":"seed"}},"/edition":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"09145f813250fe","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"09145f813250fe","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"09145f813250fe","origin":"seed"}},"/seo/description":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0e709248f75832","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0e709248f75832","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0e709248f75832","origin":"seed"}},"/seo/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"046f39b5991a73","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"046f39b5991a73","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"046f39b5991a73","origin":"seed"}},"/summary":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0055e91fd37cba","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0055e91fd37cba","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0055e91fd37cba","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0438665e4b333e","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0438665e4b333e","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0438665e4b333e","origin":"seed"}}}'::jsonb, 'published'),
  ('product', 'tropical-mediterranean-french', '{"body":{"de":[{"text":"Das Mittelmeer erlebt die volle Wirkung eingewanderter Arten, von denen manche rasch invasiv werden. Besonders das östliche Mittelmeer ist direkt von Arten betroffen, die durch den Suezkanal kommen, ein Phänomen, das als lessepsische Migration bekannt ist. Wir beobachten seine Folgen für die marine Artenvielfalt mit Faszination und Sorge zugleich.","type":"p"},{"text":"Dieses Buch erhebt keinen Anspruch auf Wissenschaftlichkeit oder Vollständigkeit. Es zeigt in ästhetischer Herangehensweise exotische Meeresarten, die zwischen 2000 und 2024 in der Region Kaş beobachtet wurden. In dieser zweiten, erweiterten Auflage (die erste hieß „Red Sea in the Med“) werden 76 Arten mit mehr als 200 Fotos und kurzen Kommentaren vorgestellt, dazu 31 Amateurvideos über QR-Codes.","type":"p"}],"en":[{"text":"The Mediterranean is experiencing the full impact of exotic species, some of which are rapidly becoming invasive. At the forefront, the Eastern Mediterranean is directly affected by species arriving through the Suez Canal, a phenomenon known as Lessepsian migration. We closely observe its effects on marine biodiversity, torn between fascination and concern.","type":"p"},{"text":"This book does not claim to be scientific or exhaustive. It offers an aesthetic approach based on observations of exotic marine species in the Kaş region between 2000 and 2024. In this second expanded edition (the first edition was called “Red Sea in the Med”), 76 species are presented through more than 200 photographs with concise commentary, plus 31 amateur videos accessible via QR codes.","type":"p"}],"fr":[{"text":"La Méditerranée subit de plein fouet l''impact des espèces exotiques, dont certaines deviennent rapidement invasives. En première ligne, la Méditerranée orientale est directement affectée par les espèces venues par le canal de Suez, un phénomène connu sous le nom de migration lessepsienne. Nous en observons les effets sur la biodiversité marine, partagés entre fascination et inquiétude.","type":"p"},{"text":"Ce livre n''a pas la prétention d''être un ouvrage scientifique ou exhaustif. Il propose une approche esthétique, à travers des observations d''espèces marines exotiques dans la région de Kaş entre 2000 et 2024. Dans cette 2e édition augmentée (la première s''intitulait « Red Sea in the Med »), 76 espèces sont présentées au fil de plus de 200 photos accompagnées de commentaires concis, ainsi que 31 vidéos amateurs accessibles par codes QR.","type":"p"}],"tr":[{"text":"Akdeniz, bazıları hızla istilacı hale gelen göçmen türlerin etkisini tam anlamıyla yaşamaktadır. Özellikle Doğu Akdeniz, Süveyş Kanalı yoluyla gelen bu türlerden doğrudan etkilenmektedir. Lesepsiyen göçü denen bu olgunun deniz biyolojik çeşitliliği üzerindeki etkilerini hem hayranlık hem de endişeyle yakından gözlemliyoruz.","type":"p"},{"text":"Bu kitap bilimsellik ya da bütünlük iddiasından çok estetik bir yaklaşımla, 2000 ile 2024 yılları arasında Kaş bölgesinde gözlemlenen egzotik deniz türlerini sunuyor. İlk baskısı “Akdeniz''de Kızıldeniz – Red Sea in the Med” adını taşıyan bu ikinci genişletilmiş baskıda 76 tür, 200''den fazla fotoğraf ve kısa yorumlarla anlatılıyor; karekodlarla erişilebilen 31 amatör video da eklendi.","type":"p"}]},"cover":"book-tropical-mediterranean-fr","currency":"EUR","edition":{"de":"Französische Ausgabe","en":"French edition","fr":"Édition française","tr":"Fransızca baskı"},"gallery":["book-tropical-spread-1","book-tropical-spread-2","book-tropical-spread-3","book-tropical-spread-4"],"id":"tropical-mediterranean-french","order":4,"origin":"cloner","price":39,"priceVerified":false,"seo":{"description":{"de":"76 exotische Meeresarten aus dem Roten Meer, beobachtet in Kaş zwischen 2000 und 2024, in über 200 Fotos. Die erweiterte zweite Auflage auf Französisch.","en":"76 exotic marine species from the Red Sea, observed in Kaş between 2000 and 2024, in more than 200 photographs. The expanded second edition, in French.","fr":"76 espèces marines exotiques venues de la mer Rouge, observées à Kaş entre 2000 et 2024, en plus de 200 photos. Deuxième édition augmentée, en français.","tr":"Kaş''ta 2000–2024 arasında gözlemlenen ve Kızıldeniz''den gelen 76 egzotik deniz türü, 200''ü aşkın fotoğrafla. Genişletilmiş 2. baskı, Fransızca."},"title":{"de":"Méditerranée tropicale – französische Ausgabe","en":"Méditerranée tropicale – French Edition","fr":"Méditerranée tropicale : 76 espèces exotiques","tr":"Méditerranée tropicale: Fransızca Baskı, 76 Tür"}},"slug":{"de":"tropisches-mittelmeer-franzoesisch","en":"tropical-mediterranean-french","fr":"mediterranee-tropicale-francais","tr":"tropikal-akdeniz-fransizca"},"sourceRefs":["products.csv","https://dragoman-turkey.com/tr/urun/tropikal-akdeniz-fransizca/","https://dragoman-turkey.com/product/tropical-mediterranean-french/","164","158","993"],"status":"published","summary":{"de":"76 exotische Meeresarten aus dem Roten Meer, beobachtet in Kaş zwischen 2000 und 2024.","en":"76 exotic marine species from the Red Sea, observed in Kaş between 2000 and 2024.","fr":"76 espèces marines exotiques venues de la mer Rouge, observées à Kaş entre 2000 et 2024.","tr":"Kaş''ta 2000–2024 arasında gözlemlenen, Kızıldeniz''den gelen 76 egzotik deniz türü."},"title":{"de":"Méditerranée tropicale","en":"Méditerranée tropicale","fr":"Méditerranée tropicale","tr":"Méditerranée tropicale"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/body":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0bae62f9909eb5","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0bae62f9909eb5","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0bae62f9909eb5","origin":"seed"}},"/edition":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"1010ff00285ca0","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"1010ff00285ca0","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"1010ff00285ca0"