  ('service_offer', 'konaklama-pansiyon-merkez', '{"cover":"lodging-guesthouse-room-1","id":"konaklama-pansiyon-merkez","kind":"lodging","order":2,"origin":"cloner","sourceRefs":["https://dragoman-turkey.com/tr/ulasim-konaklama/","https://dragoman-turkey.com/transportation-and-accomodation/","https://dragoman-turkey.com/fr/transport-et-hebergement/"],"summary":{"de":"Zu Fuß nah am Stadtzentrum und an unserem Tauchboot; alle Zimmer mit eigenem Bad und Klimaanlage. Einzel-, Doppel- und Familienzimmer (Familienzimmer für bis zu 3 Personen). Bei Einzelbelegung reduziert sich der Zimmerpreis um 5 €.","en":"Within walking distance of the town centre and our dive boat; all rooms have a private bathroom and air conditioning. Single, double and family rooms (family rooms for up to 3 people). For single occupancy the room price is reduced by €5.","fr":"À quelques pas du centre-ville et de notre bateau de plongée ; toutes les chambres ont salle de bain privée et climatisation. Chambres simples, doubles et familiales (jusqu''à 3 personnes). En occupation simple, le prix de la chambre est réduit de 5 €.","tr":"Şehir merkezine ve dalış teknemize yürüme mesafesinde; tüm odaları özel banyolu, klimalı. Tek, çift ve aile odaları (aile odaları 3 kişiye kadar). Tek kişilik konaklamada oda fiyatından 5 € düşülür."},"title":{"de":"Pension, Zentrum von Kaş","en":"Guesthouse, Kaş centre","fr":"Pension, centre de Kaş","tr":"Pansiyon, Kaş merkez"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/summary":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0e904c3a7d5d8e","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0e904c3a7d5d8e","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0e904c3a7d5d8e","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0917b94d7c33c2","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0917b94d7c33c2","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0917b94d7c33c2","origin":"seed"}}}'::jsonb, 'published'),
  ('service_offer', 'konaklama-uc-yildizli-otel', '{"cover":"lodging-hotel-pool-1","id":"konaklama-uc-yildizli-otel","kind":"lodging","order":1,"origin":"cloner","sourceRefs":["https://dragoman-turkey.com/tr/ulasim-konaklama/","https://dragoman-turkey.com/transportation-and-accomodation/","https://dragoman-turkey.com/fr/transport-et-hebergement/"],"summary":{"de":"Direkt am Wasser mit eigenem Strand und Pool, ganz in der Nähe von Stadtzentrum und Hafen. Klimatisierte Zimmer mit Balkon und Meerblick, 2 oder 3 Betten, Frühstücksbuffet, Terrasse, Bar und Restaurant. Halbpensionszuschlag 10 €/Tag. Aktuelle Preise und Verfügbarkeit auf Anfrage.","en":"On the waterfront with a private beach and pool, very close to the town centre and the harbour. Sea-view rooms with balcony, 2 or 3 beds and air conditioning, open buffet breakfast, terrace, bar and restaurant. Half-board supplement €10/day. Please contact us for up-to-date prices and availability.","fr":"En bord de mer avec plage privée et piscine, tout près du centre-ville et du port. Chambres climatisées avec balcon vue mer, 2 ou 3 lits, petit-déjeuner buffet, terrasse, bar et restaurant. Supplément demi-pension : 10 €/jour. Contactez-nous pour les tarifs et disponibilités à jour.","tr":"Sahilde, özel plajlı ve havuzlu; şehir merkezine ve limana çok yakın. Balkonlu, deniz manzaralı 2 ve 3 yataklı klimalı odalar, açık büfe kahvaltı, teras, bar ve restoran. Yarım pansiyon ek ücreti 10 €/gün. Güncel fiyat ve müsaitlik için bize yazın."},"title":{"de":"3-Sterne-Hotel, Küçükçakıl","en":"3-star hotel, Küçükçakıl","fr":"Hôtel 3 étoiles, Küçükçakıl","tr":"3 yıldızlı otel, Küçükçakıl"},"translationOrigin":{"de":"mockup","en":"cloner","fr":"cloner"}}'::jsonb, '{"/summary":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"159eeef6474b27","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"159eeef6474b27","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"159eeef6474b27","origin":"seed"}},"/title":{"de":{"at":"2026-11-01T00:00:00.000Z","hash":"0c61a8c7d7fe03","origin":"seed"},"en":{"at":"2026-11-01T00:00:00.000Z","hash":"0c61a8c7d7fe03","origin":"seed"},"fr":{"at":"2026-11-01T00:00:00.000Z","hash":"0c61a8c7d7fe03","origin":"seed"}}}'::jsonb, 'published'),
