":2,"title":{"de":"Tauchgänge für Brevetierte und Tauchreisen","en":"Certified dives and trips","fr":"Plongées pour plongeurs certifiés et voyages","tr":"Sertifikalı dalışlar ve geziler"}},{"category":"outdoor","id":"doga-bisiklet","order":3,"title":{"de":"Radtouren","en":"Cycling tours","fr":"Circuits à vélo","tr":"Bisiklet turları"}},{"category":"outdoor","id":"doga-coklu-aktivite","order":1,"title":{"de":"Multiaktivitätstouren","en":"Multi-activity tours","fr":"Circuits multi-activités","tr":"Çoklu aktivite turları"}},{"category":"outdoor","id":"doga-kiyi-tirmanisi","order":4,"title":{"de":"Coasteering","en":"Coasteering","fr":"Coasteering","tr":"Coasteering (kıyı tırmanışı)"}},{"category":"outdoor","id":"doga-kultur","order":6,"title":{"de":"Kulturtouren","en":"Culture tours","fr":"Circuits culturels","tr":"Kültür turları"}},{"category":"outdoor","id":"doga-ozel-turlar","order":7,"title":{"de":"Private Touren","en":"Private tours","fr":"Circuits privés","tr":"Özel turlar"}},{"category":"outdoor","id":"doga-tekne","order":5,"title":{"de":"Bootsausflüge","en":"Boat trips","fr":"Excursions en bateau","tr":"Tekne turları"}},{"category":"outdoor","id":"doga-yuruyus","order":2,"title":{"de":"Wandern","en":"Hiking","fr":"Randonnée","tr":"Yürüyüş"}},{"category":"seaKayak","id":"kano-cok-gunlu","intro":{"de":"Mehrere Tage paddeln, übernachten und entdecken entlang der lykischen und karischen Küste.","en":"Paddle, stay overnight and explore along the Lycian and Carian coasts for several days.","fr":"Pagayez, faites étape et explorez les côtes lycienne et carienne pendant plusieurs jours.","tr":"Likya ve Karia kıyıları boyunca birkaç gün kürek çekin, konaklayın ve keşfedin."},"order":2,"title":{"de":"Mehrtagestouren","en":"Multi-day tours","fr":"Circuits de plusieurs jours","tr":"Çok günlü turlar"}},{"category":"seaKayak","id":"kano-gunluk","intro":{"de":"Kekova-Routen mit Abfahrt in Kaş am Morgen und Rückkehr am Nachmittag.","en":"Kekova routes that leave Kaş in the morni